// Learn Logo, part 1: units 1 to 8, from the first FORWARD to decisions.
(function (LG) {
  'use strict';
  LG.LESSONS = (LG.LESSONS || []).concat([

    // ---------------------------------------------------------------- 1. Meet the turtle
    { id: 'turtle-look-around', unit: '1. Meet the turtle', title: 'A look around', level: 'Everyone', minutes: 2,
      summary: 'A one-minute tour of the turtle world, the command center, the editor and the buttons.', tour: 'welcome' },

    { id: 'turtle-first-steps', unit: '1. Meet the turtle', title: 'First steps', level: 'Kids', minutes: 6,
      summary: 'Move the turtle with FORWARD and BACK and turn it with RIGHT and LEFT.',
      steps: [
        { title: 'Say hello to the turtle', sel: '#worldCard', text: 'This is the <b>turtle</b>. It sits in the middle of its world and holds a pen. When it walks, the pen draws a line behind it. You tell it where to go with commands.' },
        { title: 'Walk forward', sel: '#cmdInputBox', text: 'This box is the <b>command center</b>. Type <code>forward 100</code> and press <kbd>Enter</kbd>. The turtle walks 100 steps the way it is facing.', check: { command: '\\b(forward|fd)\\s+\\d' }, hint: 'Click in the box first, then type. Put a space between forward and 100.' },
        { title: 'Turn', sel: '#cmdInputBox', text: 'Now type <code>right 90</code>. The turtle does not move. It only turns on the spot, a quarter of a full turn to its right.', check: { command: '\\b(right|rt)\\s+\\d' } },
        { title: 'Short names', sel: '#cmdInputBox', text: 'Logo people are lazy typists. <code>fd</code> means forward, <code>bk</code> means back, <code>rt</code> means right and <code>lt</code> means left. Try <code>fd 50 lt 90 fd 50</code>. You can put several commands on one line.', check: { command: '\\bfd\\b.*\\b(lt|left)\\b' } },
        { title: 'Backwards', sel: '#cmdInputBox', text: 'Type <code>bk 100</code>. The turtle walks backwards without turning around, like a car in reverse.', check: { command: '\\b(bk|back)\\s+\\d' } },
        { title: 'Challenge: a square', sel: '#cmdInputBox', text: 'Draw a square by yourself. You need four sides and four turns. Type one line, or several, it is up to you.', check: { drawn: 4 }, hint: 'fd 100 rt 90 fd 100 rt 90 fd 100 rt 90 fd 100 rt 90' },
        { title: 'Quick quiz', quiz: { q: 'Which way does <code>right 90</code> turn the turtle?', options: ['A quarter turn clockwise, on the spot', 'Half a turn', 'It slides to the right without turning'], answer: 0, explain: 'RIGHT turns on the spot. 90 is a quarter of a full turn of 360.' } },
        { title: 'One more', quiz: { q: 'The turtle faces up. You type <code>bk 50</code>. Where does it end up?', options: ['50 steps lower, still facing up', '50 steps higher', '50 steps lower, now facing down'], answer: 0, explain: 'BACK moves the turtle the other way without turning it.' } },
      ] },

    { id: 'turtle-pen', unit: '1. Meet the turtle', title: 'The pen and a clean page', level: 'Kids', minutes: 6,
      summary: 'Lift and lower the pen, go HOME, clear the screen and hide the turtle.',
      steps: [
        { title: 'A fresh page', sel: '#cmdInputBox', text: 'Type <code>clearscreen</code> (or just <code>cs</code>). The drawing disappears and the turtle goes back to the middle, facing up.', check: { command: '^\\s*(clearscreen|cs)\\b' } },
        { title: 'Pen up', sel: '#cmdInputBox', text: 'Type <code>penup fd 80</code>. The turtle moves but draws nothing, because its pen is lifted off the paper. <code>pu</code> is the short name.', check: { command: '\\b(penup|pu)\\b' } },
        { title: 'Pen down', sel: '#cmdInputBox', text: 'Now type <code>pendown fd 80</code> (short name <code>pd</code>). The line starts where the pen touched the paper again.', check: { command: '\\b(pendown|pd)\\b' } },
        { title: 'A dashed line', sel: '#cmdInputBox', text: 'Try a dashed line: <code>rt 90 fd 20 pu fd 20 pd fd 20 pu fd 20 pd fd 20</code>.', check: { command: '\\bpu\\b.*\\bpd\\b' } },
        { title: 'Going home', sel: '#cmdInputBox', text: 'Type <code>home</code>. The turtle goes straight back to the middle and faces up again. If the pen is down, it draws a line on the way, so lift it first if you want to go home quietly.', check: { command: '\\bhome\\b' } },
        { title: 'Hide and show', sel: '#cmdInputBox', text: 'Type <code>hideturtle</code> (<code>ht</code>). The turtle hides, which makes a finished picture look neat, and it still draws while hidden. <code>showturtle</code> (<code>st</code>) brings it back.', check: { command: '\\b(hideturtle|ht|showturtle|st)\\b' } },
        { title: 'Challenge: two squares apart', sel: '#cmdInputBox', text: 'Clear the screen, then draw a small square, lift the pen, move away, put the pen down and draw another square.', check: { drawn: 8 }, hint: 'cs fd 50 rt 90 fd 50 rt 90 fd 50 rt 90 fd 50 rt 90 pu bk 100 pd fd 50 rt 90 fd 50 rt 90 fd 50 rt 90 fd 50 rt 90' },
        { title: 'Quick quiz', quiz: { q: 'You typed <code>pu</code> and then <code>fd 100</code>. What happened?', options: ['The turtle moved 100 steps and drew nothing', 'Nothing at all', 'The turtle drew a line 100 steps long'], answer: 0, explain: 'With the pen up the turtle still moves. It just leaves no line.' } },
        { title: 'One more', quiz: { q: 'What is the difference between <code>home</code> and <code>cs</code>?', options: ['HOME moves the turtle to the middle; CS also wipes the drawing', 'They are the same', 'HOME wipes the drawing; CS only moves the turtle'], answer: 0, explain: 'CLEARSCREEN clears the picture and sends the turtle home. HOME only moves the turtle.' } },
      ] },

    { id: 'turtle-angles', unit: '1. Meet the turtle', title: 'Turning and angles', level: 'Kids', minutes: 7,
      summary: 'Angles in degrees, the full 360 turn, and what the turtle\'s heading is.',
      steps: [
        { title: 'A full turn is 360', sel: '#worldCard', text: 'Turns are measured in <b>degrees</b>. Turning all the way around, back to where you started, is <b>360</b>. Half a turn is 180, and a quarter turn is 90.' },
        { title: 'Turn all the way', sel: '#cmdInputBox', text: 'Type <code>cs rt 360</code>. The turtle spins right around and faces the same way as before.', check: { command: '\\b(rt|right)\\s+360\\b' } },
        { title: 'Half a turn', sel: '#cmdInputBox', text: 'Type <code>fd 100 rt 180 fd 50</code>. After half a turn the turtle walks back the way it came.', check: { command: '\\b(rt|right|lt|left)\\s+180\\b' } },
        { title: 'Smaller angles', sel: '#cmdInputBox', text: 'Angles do not have to be 90. Try <code>cs rt 45 fd 100</code>. That is half of a right angle, so the line goes up and to the right, slanted.', check: { command: '\\b(rt|right|lt|left)\\s+45\\b' } },
        { title: 'The heading', sel: '#cmdInputBox', text: 'The way the turtle faces is its <b>heading</b>. Up is 0, right is 90, down is 180 and left is 270, going clockwise like a compass. Type <code>print heading</code> to ask the turtle.', check: { output: '\\d' } },
        { title: 'Set the heading directly', sel: '#cmdInputBox', text: '<code>setheading</code> (<code>seth</code>) turns the turtle to face an exact direction, no matter where it faced before. Try <code>seth 90 fd 100</code>.', check: { command: '\\b(seth|setheading)\\s+\\d' } },
        { title: 'Challenge: a slanted square', sel: '#cmdInputBox', text: 'Clear the screen, turn 30 degrees, then draw a square. The square comes out tilted.', check: { drawn: 4 }, hint: 'cs rt 30 fd 100 rt 90 fd 100 rt 90 fd 100 rt 90 fd 100 rt 90' },
        { title: 'Quick quiz', quiz: { q: 'The turtle faces right (heading 90). You type <code>lt 90</code>. What is its heading now?', options: ['0, facing up', '180, facing down', '90, it did not change'], answer: 0, explain: 'LEFT turns counterclockwise, so 90 minus 90 is 0, which is up.' } },
        { title: 'One more', quiz: { q: 'Which of these leaves the turtle facing the same way it started?', options: ['<code>rt 360</code>', '<code>rt 180</code>', '<code>lt 90</code>'], answer: 0, explain: '360 degrees is a full turn, so the turtle ends where it began.' } },
      ] },

    // ---------------------------------------------------------------- 2. Repeat
    { id: 'repeat-squares', unit: '2. Repeat', title: 'Say it once with REPEAT', level: 'Kids', minutes: 6,
      summary: 'Use REPEAT to draw squares and triangles without typing the same thing over and over.',
      steps: [
        { title: 'Too much typing', sel: '#cmdCard', text: 'To draw a square you typed <code>fd 100 rt 90</code> four times. Computers are good at doing the same thing again, so Logo has a word for it: <b>REPEAT</b>.' },
        { title: 'REPEAT a square', sel: '#cmdInputBox', text: 'Type <code>cs repeat 4 [fd 100 rt 90]</code>. REPEAT takes a number and a list of commands in square brackets, and runs the list that many times.', check: { command: '\\brepeat\\s+4\\s*\\[' }, hint: 'The square brackets [ and ] are next to the P key on most keyboards.' },
        { title: 'A triangle', sel: '#cmdInputBox', text: 'A triangle has three sides. Try <code>cs repeat 3 [fd 100 rt 120]</code>. Why 120 and not 60? The turtle turns at each corner, and three turns must add up to a full 360.', check: { command: '\\brepeat\\s+3\\s*\\[' } },
        { title: 'In a program', sel: '#editorCard', text: 'Here is a program with a square and a triangle side by side. The lines run from top to bottom.', code: 'cs\nrepeat 4 [fd 100 rt 90]\npu rt 90 fd 150 lt 90 pd\nrepeat 3 [fd 100 rt 120]\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd> or the Run button. Every run starts on a clean page.', check: { run: true } },
        { title: 'Challenge: a big square', sel: '#editorCard', text: 'Change the program so the square has sides of 150 instead of 100, then run it again.', check: { codeHas: 'repeat\\s+4\\s*\\[\\s*(fd|forward)\\s+150' }, hint: 'Change the first REPEAT line to repeat 4 [fd 150 rt 90].' },
        { title: 'Quick quiz', quiz: { q: 'What does <code>repeat 3 [fd 50 rt 120]</code> draw?', options: ['A triangle', 'A square', 'Three separate lines in a row'], answer: 0, explain: 'Three sides and three turns of 120 make a full 360, so the turtle comes back to the start.' } },
        { title: 'One more', quiz: { q: 'In <code>repeat 4 [fd 100 rt 90]</code>, what is inside the square brackets?', options: ['The commands to repeat', 'How many times to repeat', 'A comment'], answer: 0, explain: 'The number says how many times; the list in brackets says what to do each time.' } },
      ] },

    { id: 'repeat-polygons', unit: '2. Repeat', title: 'Any shape: the 360 rule', level: 'Kids', minutes: 7,
      summary: 'Draw any regular polygon by turning 360 divided by the number of sides.',
      steps: [
        { title: 'The turtle\'s trip', sel: '#worldCard', text: 'When the turtle draws a closed shape and comes back to where it started, facing the same way, it has turned all the way around: <b>360 degrees</b> in total.' },
        { title: 'The rule', sel: '#worldCard', text: 'So for a shape with <b>N</b> equal sides, each turn is <b>360 / N</b>. Square: 360 / 4 = 90. Triangle: 360 / 3 = 120. Logo can work out the division for you.' },
        { title: 'A hexagon', sel: '#cmdInputBox', text: 'A hexagon has 6 sides. Type <code>cs repeat 6 [fd 80 rt 360 / 6]</code>. The turtle does the maths each time.', check: { command: '\\brepeat\\s+6\\b' } },
        { title: 'A whole family', sel: '#editorCard', text: 'This program draws a pentagon, an octagon and a 20-sided shape on top of each other.', code: 'cs\nrepeat 5 [fd 100 rt 360 / 5]\nrepeat 8 [fd 70 rt 360 / 8]\nrepeat 20 [fd 30 rt 360 / 20]\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>. The more sides, the rounder the shape looks.', check: { run: true } },
        { title: 'Almost a circle', sel: '#cmdInputBox', text: 'Try <code>cs repeat 36 [fd 10 rt 10]</code>. Thirty-six tiny sides look just like a circle. That is how the turtle draws circles.', check: { command: '\\brepeat\\s+36\\b' } },
        { title: 'Challenge: a nonagon', sel: '#cmdInputBox', text: 'A nonagon has 9 sides. Draw one with sides of 60.', check: { command: '\\brepeat\\s+9\\s*\\[.*(360\\s*/\\s*9|\\b40\\b)' }, hint: 'cs repeat 9 [fd 60 rt 360 / 9]' },
        { title: 'Quick quiz', quiz: { q: 'How much should the turtle turn at each corner of a regular 10-sided shape?', options: ['36', '10', '100'], answer: 0, explain: '360 / 10 = 36.' } },
        { title: 'One more', quiz: { q: 'Why does <code>repeat 36 [fd 10 rt 10]</code> look round?', options: ['Many short sides with small turns look like a curve', 'Logo has a hidden circle command inside REPEAT', 'Because 36 is a magic number'], answer: 0, explain: 'A circle is really a polygon with so many tiny sides you cannot see the corners.' } },
      ] },

    { id: 'repeat-stars', unit: '2. Repeat', title: 'Stars', level: 'Kids', minutes: 6,
      summary: 'Turn more than once around and you get stars like the pentagram.',
      steps: [
        { title: 'Turning too far', sel: '#worldCard', text: 'In a pentagon the turtle turns 72 each time and goes once around. What if it turns twice as far, 144? Then it goes around <b>twice</b> while it draws, and the lines cross.' },
        { title: 'A pentagram', sel: '#cmdInputBox', text: 'Type <code>cs repeat 5 [fd 150 rt 144]</code>. Five lines, five turns of 144, and you get a five-pointed star.', check: { command: '\\brepeat\\s+5\\s*\\[.*144' } },
        { title: 'Why it closes', sel: '#worldCard', text: 'Five turns of 144 add up to 720, which is exactly two full turns. The star closes because the total is a whole number of 360s.' },
        { title: 'More stars', sel: '#editorCard', text: 'For a star with an odd number of points P, turn <code>180 - 180 / P</code>. This program draws a 7-point and a 9-point star.', code: 'cs\nrepeat 7 [fd 150 rt 180 - 180 / 7]\npu setheading 0 rt 90 fd 200 lt 90 pd\nrepeat 9 [fd 120 rt 180 - 180 / 9]\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd> and look at both stars.', check: { run: true } },
        { title: 'Challenge: a spiky star', sel: '#cmdInputBox', text: 'Try <code>cs repeat 18 [fd 200 rt 160]</code>. Change 160 to other numbers like 170 or 150 and see which ones close.', check: { command: '\\brepeat\\s+\\d+\\s*\\[.*(rt|right)\\s+1[5-7]\\d' } },
        { title: 'Quick quiz', quiz: { q: 'In <code>repeat 5 [fd 150 rt 144]</code>, how far does the turtle turn in total?', options: ['720 degrees, two full turns', '360 degrees, one full turn', '144 degrees'], answer: 0, explain: '5 times 144 is 720.' } },
      ] },

    { id: 'repeat-repcount', unit: '2. Repeat', title: 'REPCOUNT and growing patterns', level: 'Kids', minutes: 7,
      summary: 'REPCOUNT tells you which time around REPEAT is on, so shapes can grow.',
      steps: [
        { title: 'Which time is it?', sel: '#cmdInputBox', text: 'Inside a REPEAT, <code>repcount</code> is the number of the current time around: 1 the first time, 2 the second, and so on. Type <code>repeat 5 [print repcount]</code>.', check: { output: '1\\s+2\\s+3\\s+4\\s+5' } },
        { title: 'Growing lines', sel: '#editorCard', text: 'Use REPCOUNT as a length and each line is longer than the one before. This makes a square spiral.', code: 'cs\nrepeat 60 [fd repcount * 4 rt 90]\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>. The first line is 4 steps, the second 8, then 12, and the turtle walks outwards.', check: { run: true } },
        { title: 'Twist it', sel: '#editorCard', text: 'Change <code>rt 90</code> to <code>rt 91</code> and run again. One extra degree each corner makes the spiral twist.', check: { codeHas: '(rt|right)\\s+(8[5-9]|9[1-9]|1[0-9]\\d)' }, hint: 'repeat 60 [fd repcount * 4 rt 91]' },
        { title: 'Run the twist', sel: '#tbRun', text: 'Press <kbd>F5</kbd>.', check: { run: true } },
        { title: 'Challenge: a triangle spiral', sel: '#cmdInputBox', text: 'Make a spiral with three-sided corners. Use <code>rt 120</code> (or 121 for a twist) and lines that grow with <code>repcount</code>.', check: { command: '\\brepcount\\b.*\\b(rt|right)\\s+12\\d' }, hint: 'cs repeat 50 [fd repcount * 5 rt 121]' },
        { title: 'Quick quiz', quiz: { q: 'What does <code>repeat 3 [print repcount]</code> print?', options: ['1, 2 and 3', '3, 3 and 3', '0, 1 and 2'], answer: 0, explain: 'REPCOUNT starts at 1 and goes up by one each time around.' } },
      ] },

    { id: 'repeat-nested', unit: '2. Repeat', title: 'Repeats inside repeats', level: 'Kids', minutes: 7,
      summary: 'Put a REPEAT inside another REPEAT to make flowers and patterns.',
      steps: [
        { title: 'A shape is a command too', sel: '#cmdCard', text: 'The list inside REPEAT can hold any commands, even another REPEAT. Then you repeat a whole shape, not just a line.' },
        { title: 'Turning squares', sel: '#cmdInputBox', text: 'Type <code>cs repeat 12 [repeat 4 [fd 80 rt 90] rt 30]</code>. The inside REPEAT draws a square; the outside one draws 12 squares, turning a little between them.', check: { command: '\\brepeat\\s+\\d+\\s*\\[\\s*repeat\\b' } },
        { title: 'Count the lines', sel: '#worldCard', text: 'The inner list runs 4 times, and the whole thing runs 12 times, so the turtle drew 4 times 12 = 48 lines. And 12 turns of 30 make a full 360, so the flower closes.' },
        { title: 'A flower', sel: '#editorCard', text: 'Here a petal is a small circle, and the flower is 10 petals.', code: 'cs ht\nsetpencolor "red\nrepeat 10 [repeat 36 [fd 4 rt 10] rt 36]\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>.', check: { run: true } },
        { title: 'Which REPCOUNT?', sel: '#cmdInputBox', text: 'Inside two REPEATs, <code>repcount</code> is the count of the <b>innermost</b> one. Try <code>repeat 2 [repeat 3 [type repcount] print "]</code>: it prints 123 twice.', check: { output: '123\\s+123' } },
        { title: 'Challenge: a hexagon flower', sel: '#cmdInputBox', text: 'Draw 6 hexagons, turning 60 degrees after each one.', check: { command: '\\brepeat\\s+6\\s*\\[\\s*repeat\\s+6\\b' }, hint: 'cs repeat 6 [repeat 6 [fd 60 rt 60] rt 60]' },
        { title: 'Quick quiz', quiz: { q: 'How many lines does <code>repeat 5 [repeat 3 [fd 50 rt 120] rt 72]</code> draw?', options: ['15', '8', '5'], answer: 0, explain: '3 lines each time, 5 times: 15 lines.' } },
      ] },

    // ---------------------------------------------------------------- 3. Teaching new words
    { id: 'words-first-program', unit: '3. Teaching new words', title: 'Your first program', level: 'Kids', minutes: 4,
      summary: 'A guided tour: write a program that teaches the turtle the word SQUARE.', tour: 'first' },

    { id: 'words-to-end', unit: '3. Teaching new words', title: 'TO and END', level: 'Kids', minutes: 7,
      summary: 'Write a procedure with TO ... END in the editor, run it, and use it from the command center.',
      steps: [
        { title: 'New words', sel: '#editorCard', text: 'A <b>procedure</b> is a new word you teach Logo. It starts with <code>to</code> and its name, and stops at <code>end</code>. Everything in between is what the word means.', code: 'to triangle\n  repeat 3 [fd 100 rt 120]\nend\n' },
        { title: 'Teach it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>. Nothing is drawn. Running the program only <i>teaches</i> Logo the word TRIANGLE.', check: { run: true } },
        { title: 'Use it', sel: '#cmdInputBox', text: 'Now type <code>triangle</code> in the command center. Logo knows the word, so the turtle draws.', check: { command: '\\btriangle\\b' } },
        { title: 'Use it again', sel: '#cmdInputBox', text: 'New words work just like built-in ones. Try <code>repeat 6 [triangle rt 60]</code>.', check: { command: '\\brepeat\\b.*\\btriangle\\b' } },
        { title: 'Words and commands together', sel: '#editorCard', text: 'A program can teach a word <i>and</i> use it. Lines outside TO ... END run in order after the words are learned.', code: 'to triangle\n  repeat 3 [fd 100 rt 120]\nend\n\ncs\nrepeat 6 [triangle rt 60]\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>.', check: { run: true } },
        { title: 'Challenge: teach SQUARE', sel: '#editorCard', text: 'Add a new procedure called <code>square</code> to the program, with <code>to square</code> on the first line and <code>end</code> on the last.', check: { codeHas: 'to\\s+square\\b[\\s\\S]*\\bend\\b' }, hint: 'to square\n  repeat 4 [fd 100 rt 90]\nend' },
        { title: 'Run and try it', sel: '#cmdInputBox', text: 'Press <kbd>F5</kbd>, then type <code>square</code> in the command center.', check: { command: '\\bsquare\\b' } },
        { title: 'Quick quiz', quiz: { q: 'You ran a program that only has <code>to star ... end</code> in it. What did the turtle draw?', options: ['Nothing yet; Logo only learned the word', 'A star', 'An error message'], answer: 0, explain: 'TO ... END defines the word. You still have to use it, by typing STAR.' } },
      ] },

    { id: 'words-inputs', unit: '3. Teaching new words', title: 'Inputs', level: 'Kids', minutes: 7,
      summary: 'Give a procedure an input like :size so it can draw any size.',
      steps: [
        { title: 'One size only', sel: '#editorCard', text: 'FORWARD needs a number: <code>fd 100</code>. That number is an <b>input</b>. Your SQUARE always draws size 100. Let us give it an input too.', code: 'to square :size\n  repeat 4 [fd :size rt 90]\nend\n\ncs\nsquare 50\nsquare 100\nsquare 150\n' },
        { title: 'Read it', sel: '#editorCard', text: 'In <code>to square :size</code>, <code>:size</code> is the name of the input. Inside the procedure, <code>:size</code> means "the number you were given". The colon is read "the value of".' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>. One word, three squares of different sizes.', check: { run: true } },
        { title: 'Try other sizes', sel: '#cmdInputBox', text: 'Type <code>square 30</code>, or <code>square 200</code>, or any size you like.', check: { command: '\\bsquare\\s+\\d' } },
        { title: 'Forgot the input?', sel: '#cmdInputBox', text: 'Type <code>square</code> alone. Logo complains that SQUARE needs more inputs. Now that the word has an input, you must always give it one.', check: { command: '^\\s*square\\s*$' } },
        { title: 'Challenge: nested squares', sel: '#cmdInputBox', text: 'Use REPEAT and REPCOUNT to draw 10 squares, each bigger than the last.', check: { command: '\\brepeat\\b.*\\bsquare\\s+repcount' }, hint: 'cs repeat 10 [square repcount * 20]' },
        { title: 'Quick quiz', quiz: { q: 'In <code>to square :size</code>, what is <code>:size</code>?', options: ['The name of an input; it holds the number you give SQUARE', 'A special Logo word that always means 100', 'A comment'], answer: 0, explain: 'Each time you call SQUARE 50 or SQUARE 80, :size holds that number.' } },
      ] },

    { id: 'words-many-inputs', unit: '3. Teaching new words', title: 'Several inputs', level: 'Kids', minutes: 7,
      summary: 'Procedures can take two or more inputs, like a polygon with any number of sides.',
      steps: [
        { title: 'Two inputs', sel: '#editorCard', text: 'A procedure can have as many inputs as you need. Just list them after the name. Here is a polygon with any number of sides and any side length.', code: 'to polygon :sides :length\n  repeat :sides [fd :length rt 360 / :sides]\nend\n\ncs\npolygon 3 120\npolygon 5 80\npolygon 8 50\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>. The first number goes into <code>:sides</code> and the second into <code>:length</code>, in that order.', check: { run: true } },
        { title: 'Use it', sel: '#cmdInputBox', text: 'Type <code>polygon 6 70</code>, then try <code>polygon 40 10</code>.', check: { command: '\\bpolygon\\s+\\d+\\s+\\d' } },
        { title: 'A rectangle', sel: '#editorCard', text: 'Add this procedure below the others, then run the program:<pre>to rectangle :width :height\n  repeat 2 [fd :height rt 90 fd :width rt 90]\nend</pre>', check: { codeHas: 'to\\s+rectangle\\s+:\\w+\\s+:\\w+[\\s\\S]*end' } },
        { title: 'Run and draw', sel: '#cmdInputBox', text: 'Press <kbd>F5</kbd>, then type <code>rectangle 200 50</code>.', check: { command: '\\brectangle\\s+\\d+\\s+\\d' } },
        { title: 'Challenge: order matters', sel: '#cmdInputBox', text: 'Type <code>rectangle 50 200</code>. Same numbers, swapped. What changed, and why?', check: { command: '\\brectangle\\s+\\d+\\s+\\d' } },
        { title: 'Quick quiz', quiz: { q: 'Given <code>to polygon :sides :length</code>, what does <code>polygon 4 30</code> draw?', options: ['A square with sides of 30', 'A 30-sided shape with sides of 4', 'Four separate lines'], answer: 0, explain: 'Inputs are matched in order: 4 goes to :sides and 30 to :length.' } },
      ] },

    { id: 'words-building', unit: '3. Teaching new words', title: 'Words made of words', level: 'Kids', minutes: 8,
      summary: 'Build bigger procedures from smaller ones: a house is a square plus a triangle.',
      steps: [
        { title: 'Small pieces', sel: '#editorCard', text: 'Big programs are made of small words. Here are SQUARE and TRIANGLE, and a HOUSE built from them.', code: 'to square :size\n  repeat 4 [fd :size rt 90]\nend\n\nto triangle :size\n  repeat 3 [fd :size rt 120]\nend\n\nto house :size\n  square :size\n  fd :size rt 30\n  triangle :size\n  lt 30 bk :size\nend\n\ncs\nhouse 100\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>. HOUSE draws the walls with SQUARE, climbs to the top-left corner, tilts 30 degrees and draws the roof with TRIANGLE.', check: { run: true } },
        { title: 'Back where it started', sel: '#editorCard', text: 'Look at the last line of HOUSE: <code>lt 30 bk :size</code>. It undoes the moves, so the turtle ends where it began, facing the same way. Procedures that put the turtle back are much easier to combine.' },
        { title: 'A street', sel: '#cmdInputBox', text: 'Because HOUSE leaves the turtle tidy, a street is easy. Type <code>cs repeat 4 [house 60 pu rt 90 fd 80 lt 90 pd]</code>.', check: { command: '\\brepeat\\b.*\\bhouse\\b' } },
        { title: 'Challenge: a STREET word', sel: '#editorCard', text: 'Add a procedure <code>to street</code> that draws a row of houses, and use it on the last line instead of <code>house 100</code>.', check: { codeHas: 'to\\s+street\\b[\\s\\S]*\\bhouse\\b[\\s\\S]*\\bend\\b' }, hint: 'to street\n  repeat 4 [house 60 pu rt 90 fd 80 lt 90 pd]\nend' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>.', check: { run: true } },
        { title: 'Quick quiz', quiz: { q: 'Why does HOUSE end with <code>lt 30 bk :size</code>?', options: ['To put the turtle back where it started, facing up', 'To draw the chimney', 'Logo needs it before END'], answer: 0, explain: 'A procedure that tidies up after itself can be used again and again in a row.' } },
      ] },

    { id: 'words-workspace', unit: '3. Teaching new words', title: 'Looking at your words', level: 'Everyone', minutes: 8,
      summary: 'PO, POTS, EDIT and ERASE, and typing TO right in the command center.',
      steps: [
        { title: 'The workspace', sel: '#editorCard', text: 'The words Logo knows live in the <b>workspace</b>. Run this program to put SQUARE and DIAMOND there.', code: 'to square :size\n  repeat 4 [fd :size rt 90]\nend\n\nto diamond :size\n  rt 45 square :size lt 45\nend\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>.', check: { run: true } },
        { title: 'Print out', sel: '#cmdInputBox', text: 'Type <code>pots</code> to list the titles of your procedures. Then type <code>po "diamond</code> to print out the whole DIAMOND procedure. PO means "print out".', check: { command: '^\\s*po\\s+"' } },
        { title: 'The quote', sel: '#transcript', text: 'Why <code>"diamond</code> with a quote mark? Without it, Logo would <i>run</i> DIAMOND. The quote says "I mean the word itself, not what it does". You will see this a lot.' },
        { title: 'Edit', sel: '#cmdInputBox', text: 'Type <code>edit "square</code> (or <code>ed "square</code>). Logo opens SQUARE in the editor so you can change it.', check: { command: '^\\s*(edit|ed)\\s+"' } },
        { title: 'Define at the prompt', sel: '#cmdInputBox', text: 'You can also type a procedure right here. Type <code>to zigzag</code> and press Enter. The prompt changes to <code>&gt;</code>. Then type <code>repeat 4 [fd 30 rt 90 fd 30 lt 90]</code>, press Enter, and type <code>end</code>.', check: { defined: 'zigzag' }, hint: 'Three lines, each followed by Enter: to zigzag / repeat 4 [fd 30 rt 90 fd 30 lt 90] / end' },
        { title: 'Use it', sel: '#cmdInputBox', text: 'Type <code>zigzag</code>. A word defined at the prompt works just like one from the editor. Careful though: running a program with <kbd>F5</kbd> starts fresh and forgets it, so keep the words you like in the editor.', check: { command: '^\\s*zigzag\\b' } },
        { title: 'Erase', sel: '#cmdInputBox', text: 'Type <code>erase "zigzag</code> (<code>er</code> for short). Then try <code>zigzag</code> again: Logo no longer knows it.', check: { command: '^\\s*(erase|er)\\s+"' } },
        { title: 'Quick quiz', quiz: { q: 'What does <code>po "square</code> do?', options: ['Prints the definition of SQUARE', 'Draws a square', 'Deletes SQUARE'], answer: 0, explain: 'PO prints out. ERASE deletes, and SQUARE on its own draws.' } },
        { title: 'One more', quiz: { q: 'Why is there a quote in <code>erase "zigzag</code>?', options: ['So Logo uses the name ZIGZAG instead of running ZIGZAG', 'Quotes make commands go faster', 'It is a typo'], answer: 0, explain: 'A quote in front of a word means "this word itself".' } },
      ] },

    // ---------------------------------------------------------------- 4. Colors and the pen
    { id: 'color-pen', unit: '4. Colors and the pen', title: 'Pen colors and sizes', level: 'Kids', minutes: 7,
      summary: 'SETPENCOLOR with numbers, names and [r g b], SETPENSIZE and SETBACKGROUND.',
      steps: [
        { title: 'Color by name', sel: '#cmdInputBox', text: 'Type <code>cs setpencolor "red fd 100</code>. Short name: <code>setpc</code>. Names need the quote mark, like any word you mean as itself.', check: { command: '\\b(setpencolor|setpc)\\s+"' } },
        { title: 'Color by number', sel: '#cmdInputBox', text: 'Colors also have numbers from 0 to 15: 0 black, 1 blue, 2 green, 3 cyan, 4 red, 5 magenta, 6 yellow, 7 white, and more up to 15. Try <code>setpc 2 rt 90 fd 100</code>.', check: { command: '\\b(setpencolor|setpc)\\s+\\d' } },
        { title: 'Mix your own', sel: '#cmdInputBox', text: 'For any color at all, give a list of three numbers from 0 to 255: how much red, green and blue. Try <code>setpc [255 128 0] rt 90 fd 100</code> for orange.', check: { command: '\\b(setpencolor|setpc)\\s+\\[' } },
        { title: 'Fat pens', sel: '#cmdInputBox', text: '<code>setpensize</code> makes the line thicker. Try <code>setpensize 8 rt 90 fd 100</code>. Size 1 is the thin normal pen.', check: { command: '\\bsetpensize\\s+\\d' } },
        { title: 'Background', sel: '#cmdInputBox', text: '<code>setbackground</code> (<code>setbg</code>) paints the whole world. Try <code>setbg "black</code>. The drawing stays on top.', check: { command: '\\b(setbackground|setbg)\\b' } },
        { title: 'A rainbow program', sel: '#editorCard', text: 'This program uses REPCOUNT as a color number, so every square has a different color.', code: 'cs\nsetbackground "black\nsetpensize 3\nrepeat 15 [setpencolor repcount repeat 4 [fd 120 rt 90] rt 24]\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>.', check: { run: true } },
        { title: 'Challenge: your own color', sel: '#editorCard', text: 'Change the program to draw every square in a color you mix yourself with <code>[r g b]</code>, and with a different background.', check: { codeHas: '(setpencolor|setpc)\\s+\\[' }, hint: 'Replace setpencolor repcount with something like setpencolor [0 200 255].' },
        { title: 'Quick quiz', quiz: { q: 'Which of these is pure green?', options: ['<code>[0 255 0]</code>', '<code>[255 0 0]</code>', '<code>[0 0 255]</code>'], answer: 0, explain: 'The three numbers are red, green and blue, in that order.' } },
      ] },

    { id: 'color-fill', unit: '4. Colors and the pen', title: 'Filling shapes', level: 'Kids', minutes: 6,
      summary: 'Fill shapes with color using FILLED and FILL.',
      steps: [
        { title: 'FILLED', sel: '#cmdInputBox', text: '<code>filled</code> takes a color and a list of drawing commands. It draws the shape and fills the inside. Type <code>cs filled "yellow [repeat 4 [fd 100 rt 90]]</code>.', check: { command: '\\bfilled\\b' } },
        { title: 'Outline color', sel: '#cmdInputBox', text: 'The outline uses the pen color, and the inside uses the color you gave FILLED. Try <code>setpc "blue filled "orange [repeat 6 [fd 60 rt 60]]</code>.', check: { command: '\\bfilled\\b' } },
        { title: 'FILL like a paint bucket', sel: '#cmdInputBox', text: '<code>fill</code> works like the paint bucket in a drawing program: it pours the pen color into the area under the turtle until it reaches lines. Try <code>cs repeat 4 [fd 100 rt 90] pu rt 45 fd 20 setpc "green fill pd</code>.', check: { command: '\\bfill\\b' }, hint: 'The turtle must be inside the closed shape, with its pen up so it does not draw on the way in.' },
        { title: 'A filled picture', sel: '#editorCard', text: 'A tree with FILLED parts. The leaves are drawn after the trunk, so they cover its top: later drawing goes on top of earlier drawing.', code: 'cs ht\nsetpc "brown\nfilled "brown [repeat 2 [fd 80 rt 90 fd 20 rt 90]]\npu fd 70 lt 90 fd 50 rt 180 pd\nsetpc "forest\nfilled "green [repeat 3 [fd 120 lt 120]]\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>.', check: { run: true } },
        { title: 'Challenge: a filled star', sel: '#cmdInputBox', text: 'Draw a filled five-pointed star.', check: { command: '\\bfilled\\b.*144' }, hint: 'cs filled "yellow [repeat 5 [fd 150 rt 144]]' },
        { title: 'Quick quiz', quiz: { q: 'For FILL to color the inside of a square, where must the turtle be?', options: ['Inside the square', 'Anywhere on the screen', 'On a corner of the square'], answer: 0, explain: 'FILL starts at the turtle and spreads out until it reaches lines.' } },
      ] },

    { id: 'color-label', unit: '4. Colors and the pen', title: 'Writing with LABEL', level: 'Kids', minutes: 5,
      summary: 'Write words in the turtle world with LABEL and SETLABELHEIGHT.',
      steps: [
        { title: 'Words on the picture', sel: '#cmdInputBox', text: '<code>label</code> writes text at the turtle\'s position. Type <code>cs label "Hello</code>.', check: { command: '\\blabel\\b' } },
        { title: 'More than one word', sel: '#cmdInputBox', text: 'For several words, use a list: <code>pu bk 40 label [My first picture]</code>. A quote only works for a single word.', check: { command: '\\blabel\\s+\\[' } },
        { title: 'Bigger letters', sel: '#cmdInputBox', text: '<code>setlabelheight</code> sets the size of the letters. Try <code>setlabelheight 40 setpc "red bk 60 label "Big</code>.', check: { command: '\\bsetlabelheight\\s+\\d' } },
        { title: 'A labeled drawing', sel: '#editorCard', text: 'A sign for your house.', code: 'to square :size\n  repeat 4 [fd :size rt 90]\nend\n\ncs ht\nsquare 100\npu setheading 90 fd 10 setheading 0 fd 40 pd\nsetlabelheight 20\nsetpc "blue\nlabel [My house]\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>.', check: { run: true } },
        { title: 'Challenge: your name', sel: '#cmdInputBox', text: 'Write your name, big and in color, somewhere in the turtle world.', check: { command: '\\blabel\\b' } },
        { title: 'Quick quiz', quiz: { q: 'Which one writes the two words <i>Hello there</i>?', options: ['<code>label [Hello there]</code>', '<code>label "Hello there</code>', '<code>label Hello there</code>'], answer: 0, explain: 'A quote marks just one word. A list in brackets can hold several.' } },
      ] },

    { id: 'color-turtle-tour', unit: '4. Colors and the pen', title: 'Turtle graphics tour', level: 'Everyone', minutes: 3,
      summary: 'A short tour of colors, filled shapes, the grid, slow motion and saving a picture.', tour: 'turtle' },

    // ---------------------------------------------------------------- 5. Where is the turtle
    { id: 'where-grid', unit: '5. Where is the turtle', title: 'Coordinates', level: 'Kids', minutes: 6,
      summary: 'Every spot in the turtle world has an x and a y; the grid button shows them.',
      steps: [
        { title: 'Graph paper', sel: '#tbGrid', text: 'Click this button to put graph paper behind the drawing. The thick lines are every 100 steps.' },
        { title: 'The middle is 0 0', sel: '#worldCard', text: 'Every spot has two numbers. <b>x</b> says how far right (or left, if negative). <b>y</b> says how far up (or down, if negative). The middle is <code>0 0</code>. The world is 800 steps wide and 600 tall, so x goes from -400 to 400 and y from -300 to 300.' },
        { title: 'Watch the numbers', sel: '#cmdInputBox', text: 'Type <code>cs fd 100</code>. The turtle is now at x 0, y 100. Then <code>rt 90 fd 200</code>: now x is 200 and y is still 100.', check: { command: '\\bfd\\s+\\d' } },
        { title: 'Ask the turtle', sel: '#cmdInputBox', text: 'Type <code>show pos</code>. POS reports the position as a list <code>[x y]</code>.', check: { output: '\\[-?[\\d.]+ -?[\\d.]+\\]' } },
        { title: 'Negative numbers', sel: '#cmdInputBox', text: 'Type <code>home lt 90 fd 150 show pos</code>. Left of the middle, x is negative: <code>[-150 0]</code>.', check: { output: '\\[-150 0\\]' } },
        { title: 'Quick quiz', quiz: { q: 'Where is the spot <code>[100 -200]</code>?', options: ['Right of the middle and below it', 'Left of the middle and above it', 'Exactly in the middle'], answer: 0, explain: 'x is 100, so right; y is -200, so down.' } },
      ] },

    { id: 'where-setxy', unit: '5. Where is the turtle', title: 'Jumping to a spot', level: 'Kids', minutes: 7,
      summary: 'Move straight to a spot with SETXY, SETPOS, SETX and SETY.',
      steps: [
        { title: 'SETXY', sel: '#cmdInputBox', text: '<code>setxy</code> moves the turtle straight to a spot, without turning. Type <code>cs setxy 100 100</code>. With the pen down, it draws a line on the way.', check: { command: '\\bsetxy\\s+-?\\d' } },
        { title: 'SETPOS', sel: '#cmdInputBox', text: '<code>setpos</code> does the same but takes one list: <code>setpos [-100 100]</code>. That is handy when the position is already in a list, like the one POS gives you.', check: { command: '\\bsetpos\\s+\\[' } },
        { title: 'SETX and SETY', sel: '#cmdInputBox', text: '<code>setx</code> changes only x, and <code>sety</code> changes only y. Try <code>setx 0 sety -100</code>.', check: { command: '\\b(setx|sety)\\s+-?\\d' } },
        { title: 'Connect the dots', sel: '#editorCard', text: 'With SETXY you can draw by visiting points, without working out angles.', code: 'cs\npu setxy -150 -100 pd\nsetxy 150 -100\nsetxy 150 50\nsetxy 0 150\nsetxy -150 50\nsetxy -150 -100\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>. A house shape, made only of points. Turn on the grid to check the corners.', check: { run: true } },
        { title: 'Heading does not change', sel: '#worldCard', text: 'Notice the turtle still faces up. SETXY moves it but never turns it. FORWARD after a SETXY still goes the way it was facing.' },
        { title: 'Challenge: a big X', sel: '#cmdInputBox', text: 'Draw a big X from corner to corner: lift the pen, go to one corner, put it down, go to the opposite corner. Then do the other line.', check: { drawn: 2 }, hint: 'cs pu setxy -200 -200 pd setxy 200 200 pu setxy -200 200 pd setxy 200 -200' },
        { title: 'Quick quiz', quiz: { q: 'The turtle is at <code>[50 80]</code>. You type <code>setx -50</code>. Where is it now?', options: ['<code>[-50 80]</code>', '<code>[-50 0]</code>', '<code>[0 80]</code>'], answer: 0, explain: 'SETX only changes x. y stays 80.' } },
      ] },

    { id: 'where-asking', unit: '5. Where is the turtle', title: 'Asking the turtle', level: 'Everyone', minutes: 8,
      summary: 'POS, XCOR, YCOR and HEADING report where the turtle is; TOWARDS and DISTANCE measure to another spot.',
      steps: [
        { title: 'Operations', sel: '#cmdCard', text: 'Words like <code>fd</code> are <b>commands</b>: they do something. Words like <code>xcor</code> are <b>operations</b>: they report a value, which you must use, for example with PRINT.' },
        { title: 'XCOR, YCOR, HEADING', sel: '#cmdInputBox', text: 'Type <code>cs rt 90 fd 120 print xcor print ycor print heading</code>. You should see 120, 0 and 90.', check: { output: '120\\s+0\\s+90' } },
        { title: 'Unused values', sel: '#cmdInputBox', text: 'Now type <code>xcor</code> alone. Logo asks what to do with the value. An operation\'s answer must go somewhere.', check: { command: '^\\s*xcor\\s*$' } },
        { title: 'TOWARDS', sel: '#cmdInputBox', text: '<code>towards</code> reports the heading that points at a spot. Type <code>cs print towards [100 100]</code>. The answer is 45: up and to the right.', check: { output: '\\b45\\b' } },
        { title: 'DISTANCE', sel: '#cmdInputBox', text: '<code>distance</code> reports how far away a spot is. Type <code>print distance [300 400]</code>. From the middle that is exactly 500.', check: { output: '\\b500\\b' } },
        { title: 'Go there', sel: '#editorCard', text: 'Put them together: turn towards a spot and walk exactly the distance, the way a turtle without SETXY would.', code: 'to walkto :spot\n  setheading towards :spot\n  fd distance :spot\nend\n\ncs\nwalkto [200 100]\nwalkto [-100 150]\nwalkto [0 0]\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>. The turtle faces each spot before it walks there.', check: { run: true } },
        { title: 'Challenge: report the trip', sel: '#cmdInputBox', text: 'Move the turtle anywhere, then print how far it is from home with <code>print distance [0 0]</code>.', check: { command: '\\bdistance\\s+\\[\\s*0\\s+0\\s*\\]' } },
        { title: 'Quick quiz', quiz: { q: 'What does <code>show pos</code> print right after <code>cs</code>?', options: ['<code>[0 0]</code>', '<code>0</code>', '<code>[400 300]</code>'], answer: 0, explain: 'CS sends the turtle home to the middle, which is [0 0].' } },
        { title: 'One more', quiz: { q: 'Why does typing <code>heading</code> on its own give an error?', options: ['HEADING reports a value, and nothing uses it', 'HEADING needs an input', 'HEADING only works inside a procedure'], answer: 0, explain: 'Operations must feed their value to something, like PRINT or SETHEADING.' } },
      ] },

    { id: 'where-edges', unit: '5. Where is the turtle', title: 'The edges of the world', level: 'Everyone', minutes: 5,
      summary: 'What happens at the edge: WINDOW, WRAP and FENCE.',
      steps: [
        { title: 'Off the edge', sel: '#cmdInputBox', text: 'Type <code>cs window fd 500</code>. In <b>WINDOW</b> mode the turtle can walk off the edge and keep going where you cannot see. Lohgo starts in this mode. Type <code>home</code> to bring it back.', check: { command: '\\bwindow\\b' } },
        { title: 'WRAP', sel: '#cmdInputBox', text: 'Type <code>cs wrap rt 10 fd 1500</code>. In <b>WRAP</b> mode, a turtle that leaves at the top comes back in at the bottom, and left joins right, like an old video game.', check: { command: '\\bwrap\\b' } },
        { title: 'FENCE', sel: '#cmdInputBox', text: 'Type <code>cs fence fd 500</code>. In <b>FENCE</b> mode the edge is a wall. The turtle refuses to go past it, and Logo tells you it is out of bounds.', check: { command: '\\bfence\\b' } },
        { title: 'Back to normal', sel: '#cmdInputBox', text: 'Type <code>window</code> to go back. Each new run with <kbd>F5</kbd> also starts again in WINDOW mode.', check: { command: '\\bwindow\\b' } },
        { title: 'Wrapped art', sel: '#editorCard', text: 'In WRAP mode, a long walk makes a pattern of stripes across the whole world.', code: 'cs ht\nwrap\nrt 17\nfd 6000\nwindow\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>. Try other angles than 17 too.', check: { run: true } },
        { title: 'Quick quiz', quiz: { q: 'Which mode stops the turtle at the edge with an error?', options: ['FENCE', 'WRAP', 'WINDOW'], answer: 0, explain: 'FENCE is a wall. WRAP comes back on the other side. WINDOW lets the turtle walk off.' } },
      ] },

    // ---------------------------------------------------------------- 6. Numbers and math
    { id: 'math-print', unit: '6. Numbers and math', title: 'Logo as a calculator', level: 'Kids', minutes: 6,
      summary: 'Do sums with + - * / and see the answers with PRINT and SHOW.',
      steps: [
        { title: 'PRINT', sel: '#cmdInputBox', text: '<code>print</code> writes a value in the command center. Type <code>print 3 + 4</code>.', check: { output: '\\b7\\b' } },
        { title: 'The four signs', sel: '#cmdInputBox', text: 'Times is <code>*</code> and divide is <code>/</code>. Try <code>print 6 * 7</code>, then <code>print 7 / 2</code>.', check: { output: '3\\.5' } },
        { title: 'Spaces and minus', sel: '#cmdInputBox', text: 'Put spaces around a minus sign: <code>print 10 - 3</code>. If you write <code>10 -3</code>, Logo thinks <code>-3</code> is a separate negative number. Try both and compare.', check: { command: '\\bprint\\s+\\d+\\s+-\\s+\\d' } },
        { title: 'PRINT and SHOW', sel: '#cmdInputBox', text: 'PRINT leaves off the outer brackets of a list, and SHOW keeps them. Type <code>print [1 2 3]</code> and then <code>show [1 2 3]</code>.', check: { output: '\\[1 2 3\\]' } },
        { title: 'Maths for drawing', sel: '#editorCard', text: 'Maths works anywhere a number goes. This program uses it for side lengths and angles.', code: 'cs\nrepeat 5 [fd 300 / 2 rt 360 / 5]\nprint 360 / 5\nprint 300 / 2\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>. The turtle draws, and the program prints the numbers it used.', check: { run: true } },
        { title: 'Challenge', sel: '#cmdInputBox', text: 'How many seconds are there in a day? Make Logo work it out.', check: { output: '\\b86400\\b' }, hint: 'print 24 * 60 * 60' },
        { title: 'Quick quiz', quiz: { q: 'What does <code>print 9 / 2</code> print?', options: ['4.5', '4', '4 remainder 1'], answer: 0, explain: 'Division in Logo gives decimals when the numbers do not divide evenly.' } },
      ] },

    { id: 'math-prefix', unit: '6. Numbers and math', title: 'Prefix, infix and order', level: 'Everyone', minutes: 7,
      summary: 'SUM and PRODUCT come before their inputs, and * comes before + unless you use parentheses.',
      steps: [
        { title: 'Word first', sel: '#cmdInputBox', text: '<code>3 + 4</code> is <b>infix</b>: the sign sits in between. Logo also has <b>prefix</b> words that come first, like every other Logo word. Type <code>print sum 3 4</code>.', check: { output: '\\b7\\b' } },
        { title: 'More prefix words', sel: '#cmdInputBox', text: 'Try <code>print product 6 7</code>, <code>print difference 10 3</code> and <code>print quotient 10 4</code>.', check: { output: '\\b42\\b' } },
        { title: 'Times before plus', sel: '#cmdInputBox', text: 'Type <code>print 2 + 3 * 4</code>. The answer is 14, not 20: like in school maths, <code>*</code> and <code>/</code> happen before <code>+</code> and <code>-</code>.', check: { output: '\\b14\\b' } },
        { title: 'Parentheses first', sel: '#cmdInputBox', text: 'Parentheses change the order. Type <code>print (2 + 3) * 4</code> to get 20.', check: { output: '\\b20\\b' } },
        { title: 'A puzzle', sel: '#cmdInputBox', text: 'Type <code>print sum 3 4 * 2</code>. It prints 11. Infix signs grab their numbers <i>before</i> a word like SUM collects its inputs, so SUM gets 3 and 8.', check: { output: '\\b11\\b' } },
        { title: 'More than two', sel: '#cmdInputBox', text: 'SUM and PRODUCT normally take two inputs. Put the whole thing in parentheses to give more: <code>print (sum 1 2 3 4)</code>.', check: { output: '\\b10\\b' } },
        { title: 'Challenge', sel: '#cmdInputBox', text: 'Using only prefix words, print the value of (5 + 3) times 2.', check: { command: '\\bproduct\\b.*\\bsum\\b|\\bsum\\b.*\\bproduct\\b' }, hint: 'print product sum 5 3 2' },
        { title: 'Quick quiz', quiz: { q: 'What does <code>print 10 - 2 * 3</code> print?', options: ['4', '24', '-4'], answer: 0, explain: 'Times first: 2 * 3 is 6, then 10 - 6 is 4.' } },
        { title: 'One more', quiz: { q: 'What does <code>print sum 1 2 * 5</code> print?', options: ['11', '15', '3'], answer: 0, explain: '2 * 5 happens first, so SUM gets 1 and 10.' } },
      ] },

    { id: 'math-random', unit: '6. Numbers and math', title: 'RANDOM and random art', level: 'Kids', minutes: 7,
      summary: 'Pick surprise numbers with RANDOM and use them to make art.',
      steps: [
        { title: 'Roll a die', sel: '#cmdInputBox', text: '<code>random 6</code> picks a whole number from 0 up to 5: six possible numbers, starting at 0. Type <code>print random 6</code> a few times.', check: { output: '\\b[0-5]\\b' } },
        { title: 'One to six', sel: '#cmdInputBox', text: 'For a real die you want 1 to 6. Type <code>print (random 6) + 1</code>. The parentheses matter: <code>random 6 + 1</code> would mean <code>random 7</code>, because the + is worked out first.', check: { command: '\\(\\s*random\\s+6\\s*\\)\\s*\\+\\s*1' } },
        { title: 'Random walk', sel: '#cmdInputBox', text: 'Try <code>cs repeat 200 [fd 10 rt random 360]</code>. Every turn is a surprise.', check: { command: '\\brepeat\\b.*\\brandom\\b' } },
        { title: 'Random art', sel: '#editorCard', text: 'This program throws squares of random sizes and colors all over the world.', code: 'cs ht\nsetbackground "black\nrepeat 40 [\n  setpencolor random 16\n  setpensize 1 + random 4\n  pu setxy (random 700) - 350 (random 500) - 250 pd\n  repeat 4 [fd 10 + random 50 rt 90]\n]\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd> a few times. Each run is a new picture.', check: { run: true } },
        { title: 'Why minus 350?', sel: '#editorCard', text: '<code>random 700</code> gives 0 to 699. Taking away 350 gives -350 to 349, which spreads the shapes left and right of the middle.' },
        { title: 'Challenge: random stars', sel: '#editorCard', text: 'Change the inner line so each shape is a five-pointed star instead of a square.', check: { codeHas: '\\brepeat\\s+5\\s*\\[.*144' }, hint: 'repeat 5 [fd 20 + random 50 rt 144]' },
        { title: 'Quick quiz', quiz: { q: 'Which numbers can <code>random 3</code> give?', options: ['0, 1 or 2', '1, 2 or 3', '0, 1, 2 or 3'], answer: 0, explain: 'RANDOM n gives a whole number from 0 up to n - 1.' } },
      ] },

    { id: 'math-functions', unit: '6. Numbers and math', title: 'Maths words', level: 'Everyone', minutes: 7,
      summary: 'SQRT, POWER, ROUND, INT and REMAINDER.',
      steps: [
        { title: 'Square roots and powers', sel: '#cmdInputBox', text: 'Type <code>print sqrt 81</code> (the square root, 9) and <code>print power 2 10</code> (2 multiplied by itself 10 times, 1024).', check: { output: '\\b1024\\b' } },
        { title: 'Rounding', sel: '#cmdInputBox', text: '<code>round</code> goes to the nearest whole number; <code>int</code> just chops off the decimals. Try <code>print round 3.7</code> and <code>print int 3.7</code>.', check: { output: '\\b4\\b[\\s\\S]*\\b3\\b' } },
        { title: 'Remainders', sel: '#cmdInputBox', text: '<code>remainder</code> gives what is left over after dividing. Type <code>print remainder 17 5</code>: 17 is three 5s with 2 left.', check: { output: '\\b2\\b' } },
        { title: 'Odd or even', sel: '#cmdInputBox', text: 'A number is even when its remainder after dividing by 2 is 0. Try <code>repeat 6 [print remainder repcount 2]</code>.', check: { output: '1\\s+0\\s+1\\s+0' } },
        { title: 'A diagonal', sel: '#editorCard', text: 'The corner-to-corner line of a square with side S is S times the square root of 2. Here the turtle uses SQRT to cross a square exactly.', code: 'cs\nrepeat 4 [fd 150 rt 90]\nrt 45\nfd 150 * sqrt 2\nprint round 150 * sqrt 2\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>. The line ends right in the far corner, and the program prints its length, rounded.', check: { run: true } },
        { title: 'Challenge', sel: '#cmdInputBox', text: 'Print the remainder when 100 is divided by 7.', check: { output: '^\\s*2\\s*$|\\n2\\s*$' }, hint: 'print remainder 100 7' },
        { title: 'Quick quiz', quiz: { q: 'What is <code>int 9.9</code>?', options: ['9', '10', '9.9'], answer: 0, explain: 'INT drops the part after the decimal point. ROUND would give 10.' } },
      ] },

    // ---------------------------------------------------------------- 7. Variables
    { id: 'var-make', unit: '7. Variables', title: 'MAKE: the quote and the colon', level: 'Kids', minutes: 7,
      summary: 'Store a value in a named box with MAKE and get it back with a colon.',
      steps: [
        { title: 'A named box', sel: '#cmdCard', text: 'A <b>variable</b> is a box with a name on it that holds a value. <code>make</code> puts a value in the box.' },
        { title: 'Make one', sel: '#cmdInputBox', text: 'Type <code>make "age 10</code>. Now the box called <i>age</i> holds 10.', check: { variable: 'age', value: '.' } },
        { title: 'Get it back', sel: '#cmdInputBox', text: 'Type <code>print :age</code>. The colon means "the value in the box called age".', check: { output: '\\d' } },
        { title: 'Quote or colon?', sel: '#cmdInputBox', text: 'Now type <code>print "age</code>. It prints the word <i>age</i> itself. The <b>quote</b> means the name. The <b>colon</b> means the value. <code>:age</code> is a short way to write <code>thing "age</code>.', check: { output: '\\bage\\b' } },
        { title: 'Use it anywhere', sel: '#cmdInputBox', text: 'A variable works wherever a value goes. Try <code>make "side 80 cs repeat 4 [fd :side rt 90]</code>.', check: { command: '\\bmake\\s+"side\\b.*:side' } },
        { title: 'Words too', sel: '#cmdInputBox', text: 'Boxes can hold words and lists too. Try <code>make "pet "cat print :pet</code>.', check: { variable: 'pet', value: '.' } },
        { title: 'Variables in a program', sel: '#editorCard', text: 'Change the numbers at the top and the whole picture changes.', code: 'make "size 120\nmake "points 7\ncs\nrepeat :points [fd :size rt 180 - 180 / :points]\nprint :points\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>. Then change <code>make "points 7</code> to 9 and run again.', check: { run: true } },
        { title: 'Quick quiz', quiz: { q: 'After <code>make "x 5</code>, what does <code>print "x</code> print?', options: ['x', '5', ':x'], answer: 0, explain: 'The quote means the word itself. To get the 5, write :x.' } },
        { title: 'One more', quiz: { q: 'Which line stores 3 in a variable called <i>n</i>?', options: ['<code>make "n 3</code>', '<code>make :n 3</code>', '<code>n = 3</code>'], answer: 0, explain: 'MAKE wants the name of the box, so it gets a quote.' } },
      ] },

    { id: 'var-counters', unit: '7. Variables', title: 'Variables that change', level: 'Kids', minutes: 7,
      summary: 'Counters, totals and drawings that grow by changing a variable over and over.',
      steps: [
        { title: 'Change the box', sel: '#cmdInputBox', text: 'Type <code>make "score 0</code>, then <code>make "score :score + 1</code> a few times, then <code>print :score</code>.', check: { variable: 'score', value: '^[1-9]' } },
        { title: 'How it works', sel: '#cmdCard', text: '<code>make "score :score + 1</code> reads the old value, adds 1, and puts the new value back in the same box. That is a <b>counter</b>.' },
        { title: 'Adding up', sel: '#cmdInputBox', text: 'Add the numbers 1 to 100: <code>make "total 0 repeat 100 [make "total :total + repcount] print :total</code>.', check: { output: '\\b5050\\b' } },
        { title: 'A growing spiral', sel: '#editorCard', text: 'This spiral keeps its line length in a variable and makes it a bit longer every time.', code: 'cs\nmake "len 5\nrepeat 60 [\n  fd :len\n  rt 90\n  make "len :len + 5\n]\nprint :len\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>. It printed 305: it started at 5 and grew by 5, sixty times.', check: { run: true } },
        { title: 'Challenge: shrinking', sel: '#editorCard', text: 'Change the program so the spiral goes inwards: start <code>:len</code> at 300 and take 5 away each time.', check: { codeHas: 'make\\s+"len\\s+:len\\s*-\\s*\\d' }, hint: 'make "len 300 at the top and make "len :len - 5 inside the REPEAT.' },
        { title: 'Run the challenge', sel: '#tbRun', text: 'Press <kbd>F5</kbd>.', check: { run: true } },
        { title: 'Quick quiz', quiz: { q: 'After <code>make "n 10 make "n :n * 2 make "n :n - 5</code>, what is <code>:n</code>?', options: ['15', '10', '20'], answer: 0, explain: '10 times 2 is 20, minus 5 is 15.' } },
      ] },

    { id: 'var-local', unit: '7. Variables', title: 'Inputs, LOCAL and LOCALMAKE', level: 'Everyone', minutes: 8,
      summary: 'Inputs are variables that belong to one procedure; LOCAL and LOCALMAKE make more of them.',
      steps: [
        { title: 'Inputs are variables', sel: '#editorCard', text: 'The <code>:size</code> in <code>to square :size</code> is a variable too. But it is <b>local</b>: it exists only while SQUARE runs.', code: 'to square :size\n  repeat 4 [fd :size rt 90]\nend\n\ncs\nsquare 100\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>.', check: { run: true } },
        { title: 'Gone afterwards', sel: '#cmdInputBox', text: 'Type <code>print :size</code>. Logo says size has no value. The box was thrown away when SQUARE finished.', check: { command: 'print\\s+:size' } },
        { title: 'The trouble with MAKE', sel: '#editorCard', text: 'MAKE inside a procedure, on a name that is not local, changes a <b>global</b> box that everyone shares. Here STAR uses a helper box called <i>turn</i> and accidentally ruins the main program\'s <i>turn</i>.', code: 'to star :size\n  make "turn 144\n  repeat 5 [fd :size rt :turn]\nend\n\ncs\nmake "turn 90\nstar 100\nprint :turn\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>. The program set <i>turn</i> to 90, but it prints 144. STAR changed it.', check: { run: true } },
        { title: 'LOCALMAKE', sel: '#editorCard', text: 'Change <code>make "turn 144</code> inside STAR to <code>localmake "turn 144</code>. LOCALMAKE makes a new box that belongs only to STAR.', check: { codeHas: 'localmake\\s+"turn' } },
        { title: 'Run again', sel: '#tbRun', text: 'Press <kbd>F5</kbd>. Now it prints 90. The main program\'s box is safe.', check: { run: true } },
        { title: 'LOCAL', sel: '#editorCard', text: '<code>local "turn</code> on its own makes an empty local box; a later <code>make "turn 144</code> then fills that one. <code>localmake "turn 144</code> is the two steps at once. Use one of them for every helper variable in a procedure.' },
        { title: 'Quick quiz', quiz: { q: 'Which variables disappear when a procedure finishes?', options: ['Its inputs and anything made with LOCAL or LOCALMAKE', 'Every variable MAKE created anywhere', 'None, variables last forever'], answer: 0, explain: 'Inputs and locals belong to the procedure. Plain MAKE on a new name makes a global that stays.' } },
      ] },

    { id: 'var-scope', unit: '7. Variables', title: 'Who can see a variable?', level: 'Intermediate', minutes: 8,
      summary: 'Logo\'s dynamic scope: a procedure can see the local variables of whoever called it.',
      steps: [
        { title: 'A surprise', sel: '#editorCard', text: 'SIDE has no input called <code>:size</code>, but it uses one. Will this work?', code: 'to box :size\n  repeat 4 [side rt 90]\nend\n\nto side\n  fd :size\nend\n\ncs\nbox 60\nbox 120\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>. It works, and draws both boxes.', check: { run: true } },
        { title: 'Dynamic scope', sel: '#editorCard', text: 'When SIDE asks for <code>:size</code>, Logo looks in SIDE first, then in the procedure that called SIDE (BOX), then in whoever called BOX, and so on, out to the globals. This is called <b>dynamic scope</b>: what you see depends on who called you, not where the procedure was written.' },
        { title: 'Try it alone', sel: '#cmdInputBox', text: 'Type <code>side</code> on its own. Now no caller has a <code>:size</code>, so Logo says size has no value.', check: { command: '^\\s*side\\s*$' } },
        { title: 'Closest one wins', sel: '#editorCard', text: 'If several callers have a variable with the same name, the nearest one wins.', code: 'to outer\n  localmake "color "red\n  middle\nend\n\nto middle\n  localmake "color "blue\n  inner\nend\n\nto inner\n  print :color\nend\n\nmake "color "green\nouter\ninner\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>. Called through OUTER and MIDDLE, INNER sees blue, MIDDLE\'s box. Called from the top, it sees the global green.', check: { run: true } },
        { title: 'Good habits', sel: '#editorCard', text: 'Dynamic scope is handy, but a procedure that quietly depends on its caller\'s variables is hard to reuse. Most of the time, pass values as inputs instead: <code>to side :size</code>.' },
        { title: 'Quick quiz', quiz: { q: 'In the last program, what would INNER print if MIDDLE did not have its LOCALMAKE?', options: ['red', 'green', 'An error'], answer: 0, explain: 'The next caller out is OUTER, whose local color is red.' } },
      ] },

    // ---------------------------------------------------------------- 8. Making decisions
    { id: 'if-compare', unit: '8. Making decisions', title: 'IF and comparing', level: 'Kids', minutes: 7,
      summary: 'Run commands only when something is true, using IF with < > and =.',
      steps: [
        { title: 'True or false', sel: '#cmdInputBox', text: 'A comparison reports <code>true</code> or <code>false</code>. Type <code>print 5 > 3</code>, then <code>print 2 = 7</code>.', check: { output: 'false' } },
        { title: 'IF', sel: '#cmdInputBox', text: '<code>if</code> takes a true-or-false value and a list. It runs the list only when the value is true. Type <code>if 5 > 3 [print "yes]</code>, then <code>if 2 > 3 [print "yes]</code>.', check: { command: '^\\s*if\\b' } },
        { title: 'Words too', sel: '#cmdInputBox', text: '<code>=</code> compares words as well as numbers, and ignores upper and lower case. Try <code>print "cat = "CAT</code>.', check: { output: 'true' } },
        { title: 'Decisions in a drawing', sel: '#editorCard', text: 'This row of shapes uses IF to make every third one a triangle.', code: 'to piece :n\n  if (remainder :n 3) = 0 [repeat 3 [fd 40 rt 120]]\n  if (remainder :n 3) > 0 [repeat 4 [fd 40 rt 90]]\nend\n\ncs\npu setxy -350 0 pd\nrepeat 12 [piece repcount pu rt 90 fd 60 lt 90 pd]\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>. Shapes 3, 6, 9 and 12 are triangles. Notice the parentheses in <code>(remainder :n 3) = 0</code>. Without them Logo would work out <code>3 = 0</code> first and hand REMAINDER the word false.', check: { run: true } },
        { title: 'Challenge: hot or not', sel: '#cmdInputBox', text: 'Make a variable <code>temp</code> and use IF to print <code>[Too hot]</code> when it is above 30.', check: { command: '\\bif\\s+:temp\\s*>' }, hint: 'make "temp 35 if :temp > 30 [print [Too hot]]' },
        { title: 'Quick quiz', quiz: { q: 'What does <code>if 4 < 2 [print "hi]</code> print?', options: ['Nothing', 'hi', 'false'], answer: 0, explain: '4 < 2 is false, so IF skips the list.' } },
      ] },

    { id: 'if-ifelse', unit: '8. Making decisions', title: 'IFELSE: one or the other', level: 'Kids', minutes: 7,
      summary: 'Choose between two lists with IFELSE, and use IF and IFELSE to report a value.',
      steps: [
        { title: 'Two choices', sel: '#cmdInputBox', text: '<code>ifelse</code> takes a condition and <b>two</b> lists. It runs the first if true, the second if false. Type <code>make "n 7 ifelse :n > 5 [print "big] [print "small]</code>.', check: { output: '\\b(big|small)\\b' } },
        { title: 'Coin flip', sel: '#cmdInputBox', text: 'Combine with RANDOM: <code>repeat 5 [ifelse (random 2) = 0 [print "heads] [print "tails]]</code>.', check: { output: '(heads|tails)' } },
        { title: 'IFELSE as an operation', sel: '#cmdInputBox', text: 'IFELSE can also <b>report</b> a value: whatever the chosen list reports. Type <code>print ifelse :n > 5 ["big] ["small]</code>. Here the lists hold values, not commands.', check: { command: '\\bprint\\s+ifelse\\b' } },
        { title: 'IF reports too', sel: '#cmdInputBox', text: 'IF with three inputs in parentheses works just like IFELSE: <code>print (if :n > 5 ["big] ["small])</code>.', check: { command: '\\(\\s*if\\b' } },
        { title: 'Choosing colors', sel: '#editorCard', text: 'A checkerboard row: each square picks its color with IFELSE as an operation.', code: 'to square :size\n  repeat 4 [fd :size rt 90]\nend\n\ncs ht\npu setxy -300 0 pd\nrepeat 10 [\n  filled ifelse (remainder repcount 2) = 0 ["black] ["red] [square 50]\n  pu rt 90 fd 50 lt 90 pd\n]\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>.', check: { run: true } },
        { title: 'Challenge: the larger one', sel: '#cmdInputBox', text: 'Make variables <code>a</code> and <code>b</code> and print the larger one using IFELSE as an operation.', check: { command: '\\bprint\\s+(ifelse|\\(\\s*if)\\b.*:a.*:b|\\bprint\\s+(ifelse|\\(\\s*if)\\b.*:b.*:a' }, hint: 'make "a 12 make "b 30 print ifelse :a > :b [:a] [:b]' },
        { title: 'Quick quiz', quiz: { q: 'What does <code>print ifelse 3 = 3 ["same] ["different]</code> print?', options: ['same', 'different', 'true'], answer: 0, explain: '3 = 3 is true, so IFELSE reports what the first list reports.' } },
      ] },

    { id: 'if-logic', unit: '8. Making decisions', title: 'AND, OR, NOT', level: 'Everyone', minutes: 6,
      summary: 'Combine true and false values with AND, OR and NOT.',
      steps: [
        { title: 'AND', sel: '#cmdInputBox', text: '<code>and</code> reports true only if both inputs are true. Type <code>make "x 5 print and :x > 0 :x < 10</code>.', check: { output: 'true' } },
        { title: 'OR', sel: '#cmdInputBox', text: '<code>or</code> reports true if at least one input is true. Try <code>print or :x < 0 :x > 3</code>.', check: { command: '\\bor\\b' } },
        { title: 'NOT', sel: '#cmdInputBox', text: '<code>not</code> flips true and false. Try <code>print not :x = 5</code>.', check: { output: 'false' } },
        { title: 'Prefix words', sel: '#cmdCard', text: 'AND, OR and NOT come first, like SUM. The comparisons are infix, so they are worked out before AND gets its inputs. For more than two conditions, use parentheses: <code>(and :a :b :c)</code>.' },
        { title: 'Inside a box', sel: '#editorCard', text: 'Random dots, colored red only when they land inside the middle box.', code: 'cs ht\nsetpensize 6\nrepeat 300 [\n  make "x (random 600) - 300\n  make "y (random 400) - 200\n  ifelse and (abs :x) < 100 (abs :y) < 100 [setpc "red] [setpc "grey]\n  pu setxy :x :y pd fd 1\n]\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>. <code>abs</code> drops the minus sign, so <code>(abs :x) < 100</code> means "x is between -100 and 100".', check: { run: true } },
        { title: 'Challenge: outside', sel: '#editorCard', text: 'Change the program so the dots <b>outside</b> the box are red instead. One way is NOT, another is OR.', check: { codeHas: '\\b(not|or)\\b' }, hint: 'ifelse not and (abs :x) < 100 (abs :y) < 100 [setpc "red] [setpc "grey]' },
        { title: 'Quick quiz', quiz: { q: 'What does <code>print or "false "false</code> print?', options: ['false', 'true', 'An error'], answer: 0, explain: 'OR needs at least one true input.' } },
      ] },

    { id: 'if-test', unit: '8. Making decisions', title: 'TEST, IFTRUE, IFFALSE', level: 'Everyone', minutes: 5,
      summary: 'Ask once with TEST, then act on the answer later with IFTRUE and IFFALSE.',
      steps: [
        { title: 'Ask once', sel: '#cmdInputBox', text: '<code>test</code> remembers whether a condition is true. Then <code>iftrue</code> (<code>ift</code>) and <code>iffalse</code> (<code>iff</code>) run their lists based on that answer. Type <code>make "n 4 test :n > 3 iftrue [print "big] iffalse [print "small]</code>.', check: { output: '\\b(big|small)\\b' } },
        { title: 'Why bother?', sel: '#cmdCard', text: 'TEST is useful when you have several things to do for one answer, spread over different lines, without repeating the condition each time.' },
        { title: 'A quiz program', sel: '#editorCard', text: 'This procedure checks an answer once and acts on it twice.', code: 'to check :answer\n  test :answer = 12\n  iftrue [print [Right!]]\n  iffalse [print [Not quite.]]\n  iffalse [print [3 times 4 is 12.]]\nend\n\nprint [What is 3 times 4?]\ncheck 12\ncheck 7\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>. Then try <code>check 11</code> in the command center.', check: { run: true } },
        { title: 'Private answers', sel: '#editorCard', text: 'Each procedure has its own TEST answer. A TEST inside CHECK does not change the answer in the procedure that called CHECK.' },
        { title: 'Quick quiz', quiz: { q: 'After <code>test 2 > 5</code>, which list runs?', options: ['The one given to IFFALSE', 'The one given to IFTRUE', 'Both'], answer: 0, explain: '2 > 5 is false.' } },
      ] },

    { id: 'if-predicates', unit: '8. Making decisions', title: 'Questions about values', level: 'Intermediate', minutes: 7,
      summary: 'Predicates like NUMBERP, WORDP, LISTP, EMPTYP and MEMBERP report true or false.',
      steps: [
        { title: 'Predicates', sel: '#cmdCard', text: 'An operation that reports true or false is called a <b>predicate</b>. Most of their names end in P, for "predicate". You can put a predicate wherever IF wants a condition.' },
        { title: 'What kind of thing?', sel: '#cmdInputBox', text: 'Try <code>print numberp 42</code>, <code>print wordp "cat</code> and <code>print listp [a b]</code>. A number counts as a word too: <code>print wordp 42</code> is true.', check: { output: 'true' } },
        { title: 'Empty', sel: '#cmdInputBox', text: '<code>emptyp</code> is true for the empty list <code>[]</code> and the empty word <code>"</code>. Type <code>print emptyp []</code>.', check: { output: 'true' } },
        { title: 'Membership', sel: '#cmdInputBox', text: '<code>memberp</code> checks whether something is in a list, or a letter in a word. Try <code>print memberp "blue [red green blue]</code> and <code>print memberp "z "pizza</code>.', check: { command: '\\bmemberp\\b' } },
        { title: 'Describe anything', sel: '#editorCard', text: 'This procedure uses predicates to describe whatever it is given.', code: 'to describe :thing\n  ifelse numberp :thing [print [a number]] [\n    ifelse wordp :thing [print [a word]] [\n      ifelse emptyp :thing [print [an empty list]] [print [a list]]\n    ]\n  ]\nend\n\ndescribe 42\ndescribe "hello\ndescribe [1 2 3]\ndescribe []\n' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd>, then try <code>describe "</code> and <code>describe 3.5</code> yourself.', check: { run: true } },
        { title: 'Challenge: vowels', sel: '#cmdInputBox', text: 'Print whether the letter in a variable is a vowel. Use MEMBERP with the word <code>"aeiou</code>.', check: { command: '\\bmemberp\\b.*aeiou' }, hint: 'make "letter "e print memberp :letter "aeiou' },
        { title: 'Quick quiz', quiz: { q: 'What does <code>print emptyp [a]</code> print?', options: ['false', 'true', 'a'], answer: 0, explain: '[a] has one member, so it is not empty.' } },
        { title: 'One more', quiz: { q: 'Which is <b>true</b>?', options: ['<code>wordp 42</code>', '<code>listp "cat</code>', '<code>numberp "cat</code>'], answer: 0, explain: 'In Logo, a number is a kind of word.' } },
      ] },
  ]);
})(LG);
